window.ScripturaLexicons.BDAG_PART_0269 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-01\" data-source=\"BDAG\" data-search=\"παραζηλόω verbo provocar ciúmes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραζηλόω</td><td>verbo</td><td>provocar ciúmes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-02\" data-source=\"BDAG\" data-search=\"παραθαλάσσιος, ία adjetivo situado junto ao mar ou lago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραθαλάσσιος, ία</td><td>adjetivo</td><td>situado junto ao mar ou lago</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-03\" data-source=\"BDAG\" data-search=\"παραθαρσύνω verbo encorajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραθαρσύνω</td><td>verbo</td><td>encorajar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-04\" data-source=\"BDAG\" data-search=\"παραθεωρέω verbo negligenciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραθεωρέω</td><td>verbo</td><td>negligenciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-05\" data-source=\"BDAG\" data-search=\"παραθήκη, ης, ἡ substantivo feminino depósito confiado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραθήκη, ης, ἡ</td><td>substantivo feminino</td><td>depósito confiado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-06\" data-source=\"BDAG\" data-search=\"παράθου, παραθῶσιν remissão ver παρατίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράθου, παραθῶσιν</td><td>remissão</td><td>ver παρατίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-07\" data-source=\"BDAG\" data-search=\"παράθυρος substantivo feminino porta lateral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράθυρος</td><td>substantivo feminino</td><td>porta lateral</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-08\" data-source=\"BDAG\" data-search=\"παραινέω verbo aconselhar; exortar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραινέω</td><td>verbo</td><td>aconselhar; exortar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-09\" data-source=\"BDAG\" data-search=\"παραιτέομαι verbo médio depoente pedir; escusar-se; rejeitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραιτέομαι</td><td>verbo médio depoente</td><td>pedir; escusar-se; rejeitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-10\" data-source=\"BDAG\" data-search=\"παρακαθέζομαι verbo médio depoente sentar-se ao lado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακαθέζομαι</td><td>verbo médio depoente</td><td>sentar-se ao lado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-11\" data-source=\"BDAG\" data-search=\"παρακάθημαι verbo estar sentado ao lado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακάθημαι</td><td>verbo</td><td>estar sentado ao lado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-12\" data-source=\"BDAG\" data-search=\"παρακαθίζω verbo sentar-se junto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακαθίζω</td><td>verbo</td><td>sentar-se junto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-13\" data-source=\"BDAG\" data-search=\"παρακαθίστημι verbo posicionar ao lado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακαθίστημι</td><td>verbo</td><td>posicionar ao lado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-14\" data-source=\"BDAG\" data-search=\"παρακαλέω verbo chamar; convidar; exortar; consolar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακαλέω</td><td>verbo</td><td>chamar; convidar; exortar; consolar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-15\" data-source=\"BDAG\" data-search=\"παρακαλύπτω verbo ocultar; esconder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακαλύπτω</td><td>verbo</td><td>ocultar; esconder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-16\" data-source=\"BDAG\" data-search=\"παρακαταθήκη, ης, ἡ substantivo feminino depósito confiado à guarda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακαταθήκη, ης, ἡ</td><td>substantivo feminino</td><td>depósito confiado à guarda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-17\" data-source=\"BDAG\" data-search=\"παράκειμαι verbo estar à mão; estar disponível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράκειμαι</td><td>verbo</td><td>estar à mão; estar disponível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-18\" data-source=\"BDAG\" data-search=\"παρακέκλημαι, παρακληθῶ remissão ver παρακαλέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακέκλημαι, παρακληθῶ</td><td>remissão</td><td>ver παρακαλέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-19\" data-source=\"BDAG\" data-search=\"παρακελεύω verbo exortar; encorajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακελεύω</td><td>verbo</td><td>exortar; encorajar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0269-20\" data-source=\"BDAG\" data-search=\"παράκλησις, εως, ἡ substantivo feminino exortação; apelo; consolação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράκλησις, εως, ἡ</td><td>substantivo feminino</td><td>exortação; apelo; consolação</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0269-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραζηλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραζηλόω</span>, futuro <span class=\"greek\">παραζηλώσω</span>; 1.º aoristo <span class=\"greek\">παρεζήλωσα</span> (Hesych. = <span class=\"greek\">παροξύνω</span>), provocar ciúme, despertar ciúmes (LXX; GrBar 16:2), <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, «Provocar ciúme em alguém por causa de outra pessoa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:19</a> (Dt 32:21; cf. 4Q 372 I, 12). <span class=\"greek\">τινά</span>, «Alguém» (3 Km 14:22; Sir 30:3), 11:11 (RBell, Provoked to Jealousy ’94). <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span>, «(Irmãos segundo a) carne», v. 14. É esse sentido, mais que um sentido geral como «provocar ira», que ocorre em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:22</a>: <span class=\"greek\">ἢ</span> <span class=\"greek\">παραζηλοῦμεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span>, «Ou provocaremos o Senhor a ciúmes?», isto é, sendo infiéis a ele e recorrendo a divindades de segunda categoria (demônios). A estrutura retórica aqui depende profundamente da concepção greco-romana segundo a qual um <span class=\"greek\">δαίμων</span> é uma divindade de segunda ordem, destinada ao serviço, um «sátrapa», como Celso a denominou posteriormente (Orig., C. Cels. 8, 35, 6). Com acentuada sátira, Paulo afirma que Deus tem motivo de ciúme caso os coríntios participem de banquetes cívicos em que se oferece sacrifício a meras divindades secundárias <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">θεῷ</span> (v. 20), expressão deliberadamente ambígua, que pode referir-se tanto à divindade genericamente («um deus») quanto à divindade suprema da tradição bíblica. Na prática, os coríntios estariam insultando «o Senhor».—DELG s.v. <span class=\"greek\">ζῆλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραθαλάσσιος, ία</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραθαλάσσιος</span>, <span class=\"greek\">ία</span> (<span class=\"greek\">θάλασσα</span>; B-D-F §59, 1; Mlt-H. 158), <span class=\"greek\">ον</span> (Hdt. e outros; SIG 709, 20 [107 a.C.]; IEph III, 680, 17; LXX.—B-D-F §123, 1; Mlt-H. 320), (situado) junto ao mar ou lago, acerca de lugares (Hdt. 7, 109; Polyb. 1, 20, 6; 22, 11, 4; Ezk 25:9; 1 Macc 7:1; 11:8; 2 Macc 8:11; Jos., Bell. 1, 257): <span class=\"greek\">Καφαρναοὺμ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παραθαλασσία</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:13</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:31</a> D. Talvez AcPl BMM verso 13.—New Docs 4, 165. DELG s.v. <span class=\"greek\">θάλασσα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραθαρσύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραθαρσύνω</span> (Thu. 4, 115, 1; Diod S 14, 115, 3; Plut., Fab. 184 [17, 7], Crass. 560 [27, 1]; Herodian 3, 12, 4; 4 Macc 13:8; Jos., Ant. 12, 290; 14, 440. Os escritores áticos mais recentes têm <span class=\"greek\">παραθαρρύνω</span>), encorajar, infundir coragem, com acusativo da pessoa encorajada (X., An. 3, 1, 39; 4 Macc 13:8; Jos., Ant. 12, 305), ApcPt 2, 5.—DELG s.v. <span class=\"greek\">θάρσος</span> B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραθεωρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραθεωρέω</span> (X. e posteriores), dispensar atenção insuficiente a alguém, resultando em resposta deficiente, deixar de observar, ignorar, negligenciar (assim Hero Alex. I p. 410, 5; Diod S 40, 5; Dionys. Hal., De Isae. 18; Sb 1161, 38f [57/56 a.C.] = Mitt-Wilck. I/2, 70, 24; BGU 1786, 5 [50 a.C.]), <span class=\"greek\">τινά</span>, «Alguém», na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:1</a>.—DELG s.v. <span class=\"greek\">θεωρός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραθήκη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραθήκη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hdt. e outros; Plato Comicus [V/IV a.C.], Fgm. 158 K.; Polyb. 33, 6, 4; 9; Sext. Emp., Hyp. 3, 25, 189; Vett. Val. 39, 16; 67, 24; inscrições, papiros, LXX; TestBenj 12:2; Ps.-Phoc. 135.—Em lugar desta forma, a prosa ática apresenta <span class=\"greek\">παρακαταθήκη</span>; cf. Phryn. p. 312 Lob.; Nägeli 27), bem confiado aos cuidados de outra pessoa, depósito (cf. a expressão inglesa «to lay by», «guardar»), em linguagem figurada (já em Hdt. 9, 45, a respeito de <span class=\"greek\">ἔπεα</span>, «palavras»; também Sextus 21, acerca da alma), em nossa literatura somente nas epístolas pastorais e sempre com <span class=\"greek\">φυλάσσειν</span>, sobre o patrimônio espiritual confiado ao cristão ortodoxo. <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">φυλάσσειν</span>, «Guardar aquilo que foi confiado» (segundo CSpicq, S. Paul et la loi des dépôts: RB 40, ’31, 481–502 [ver também bibliografia adiante], termo técnico jurídico), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:12</a>, 14 (na primeira e na última passagem, variante textual <span class=\"greek\">παρακαταθήκη</span>, ver esse verbete). JRanft, artigo ‘Depositum’ em RAC III, 778–84; RLeonhard, artigo ‘Depositum’, Pauly-W. V/1, 233–36; WBarclay, ET 69, ’58, 324–27.—DELG s.v. <span class=\"greek\">τίθημι</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράθου, παραθῶσιν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράθου</span>, <span class=\"greek\">παραθῶσιν</span>: ver <span class=\"greek\">παρατίθημι</span>.5</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράθυρος</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράθυρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (desde PMichZen 38, 11 [III a.C.]), entrada lateral, porta lateral: <span class=\"greek\">ἐλθὼν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παράθυρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταδίου</span>, «O leão aproximou-se da porta lateral da arena», AcPl Ha 2, 5.—Ver DELG s.v. <span class=\"greek\">θύρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραινέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραινέω</span>, imperfeito <span class=\"greek\">παρῄνουν</span>; aoristo <span class=\"greek\">παρῄνεσα</span> na LXX, particípio <span class=\"greek\">παραινέσας</span> na LXX (Pind., Hdt. e outros; inscrições, papiros, LXX, Philo, Joseph.; TestGad 6:1), aconselhar com veemência, recomendar, exortar, <span class=\"greek\">τινά</span> (em lugar do dativo usual; ver B-D-F §152, 3; Rob. 475; e Ps.-Callisth. 3, 4, 16 <span class=\"greek\">παρῄνουν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἀλέξανδρον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Μακεδόνες</span>), seguido de infinitivo (Jos., Bell. 5, 87f, Ant. 1, 201.—B-D-F §392, 1d; 409, 5; Rdm.2 121; 226), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:22</a>. Em uso absoluto (SIG 89, 42), seguido de discurso direto, IMg 6:1; seguido de <span class=\"greek\">λέγων</span> <span class=\"greek\">αὐτοῖς</span> e discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:9</a> (sobre o imperfeito <span class=\"greek\">παρῄνει</span>, ver B-D-F §328). <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «Recomendar alguma coisa a alguém» (Oenomaus em Eus., PE 5, 25, 1; Philo, Poster. Cai. 13), ISm 4:1. <span class=\"greek\">τὶ</span> (Chion, Ep. 16, 1 <span class=\"greek\">παρῄνουν</span> <span class=\"greek\">ταῦτα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:18</a> D.—KWeidinger, Die Haustafeln: Ein Stück urchristlicher Paränese, 1928.—DELG s.v. <span class=\"greek\">αἶνος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραιτέομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραιτέομαι</span>, depoente médio; imperativo <span class=\"greek\">παραιτοῦ</span>; imperfeito <span class=\"greek\">παρῃτούμην</span>; 1.º aoristo <span class=\"greek\">παρῃτησάμην</span>. Passiva: perfeito, 3.ª pessoa singular <span class=\"greek\">παρῄτηται</span>, 1 Km 20:28; particípio <span class=\"greek\">παρῃτημένος</span> (Pind., Hdt. e posteriores).<br>\n① Fazer um pedido, pedir, solicitar (para si mesmo).<br>\nⓐ Pedir algo em favor de outra pessoa, interceder por alguém, <span class=\"greek\">τινά</span> (Polyb. 4, 51, 1; Plut., Demetr. 893a [9, 8], Thes. 8 [19, 9]. Cf. BGU 625, 7): <span class=\"greek\">δέσμιον</span>, «Um prisioneiro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:6</a> (Appian, Bell. Civ. 2, 24 §91 <span class=\"greek\">Σκαῦρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλήθους</span> <span class=\"greek\">παραιτουμένου</span> = «A multidão intercedia por Escauro»).<br>\nⓑ Seguido de infinitivo com a negação <span class=\"greek\">μή</span> (Thu. 5, 63, 3; ver B-D-F §429; Rob. 1094): <span class=\"greek\">παρῃτήσαντο</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προστεθῆναι</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">λόγον</span>, «Pediram que não lhes fosse transmitida mensagem adicional», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:19</a> (a variante textual omite <span class=\"greek\">μή</span>). Embora o efeito final seja uma recusa, o foco de <span class=\"greek\">π</span>. está no pedido, o que não ocorre na acepção 2 abaixo.<br>\n② Afastar alguma coisa mediante pedido ou súplica.<br>\nⓐ Quando <span class=\"greek\">π</span>. é usado em conexão com convite, torna-se eufemismo com o sentido de pedir dispensa, escusar-se (Polyb. 5, 27, 3); na passiva, <span class=\"greek\">ἔχε</span> <span class=\"greek\">με</span> <span class=\"greek\">παρῃτημένον</span>, «Considera-me dispensado» (ver <span class=\"greek\">ἔχω</span> 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:18b</a>, 19; como reflexivo, escusar-se (Jos., Ant. 7, 175; 12, 197), v. 18a (sobre os vários pretextos empregados para recusar um convite, ver Aristot., Fgm. 554 [VRose 1886] = Paus. Att., <span class=\"greek\">τ</span>. 37:1: minha esposa está doente; 2: o navio não está preparado para zarpar).<br>\nⓑ Recusar, rejeitar, evitar, declinar (CMRDM I, 164, 16f: um lutador é declarado vencedor quando seus adversários se recusam a enfrentá-lo ao contemplarem seu corpo despido; Diod S 13, 80, 2 em uso absoluto).<br>\n<span class=\"greek\">α</span>. Com acusativo de pessoa, rejeitar, recusar alguém ou recusar fazer algo a alguém (EpArist 184; Philo, Det. Pot. Ins. 38; Jos., Ant. 7, 167), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:25</a>ab (ouvir alguém). <span class=\"greek\">νεωτέρας</span> <span class=\"greek\">χήρας</span> <span class=\"greek\">παραιτοῦ</span>, «Recusa (inscrever) viúvas mais jovens (que 60 anos) quando solicitam auxílio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:11</a>. <span class=\"greek\">αἱρετικὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">παραιτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:10</a>; mas aqui a palavra provavelmente tem o sentido de dispensar, afastar, expulsar (cf. Diog. L. 6, 82 <span class=\"greek\">οἰκέτην</span>; Plut., Mor. 206a <span class=\"greek\">γυναῖκα</span>).<br>\n<span class=\"greek\">β</span>. Com acusativo de coisa, rejeitar, evitar (Pind., Nem. 10, 30 <span class=\"greek\">χάριν</span>; Epict. 2, 16, 42; PLond 1231, 3 [II d.C.]; Philo, Poster. Cai. 2 <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἐπικούρειον</span> <span class=\"greek\">ἀσέβειαν</span>; Jos., Ant. 3, 212; 5, 237), Dg 4:2; 6:10. <span class=\"greek\">γραώδεις</span> <span class=\"greek\">μύθους</span> <span class=\"greek\">παραιτοῦ</span>, «Rejeita as fábulas próprias de velhas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:7</a>. <span class=\"greek\">ζητήσεις</span> <span class=\"greek\">παραιτοῦ</span>, «Evita questões», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:23</a> (cf. Herm. Wr. em Stob. I 277, 21 W. = p. 432, 20 Sc. <span class=\"greek\">τὰς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ὁμιλίας</span> <span class=\"greek\">παραιτοῦ</span>).—<span class=\"greek\">οὐ</span> <span class=\"greek\">παραιτοῦμαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀποθανεῖν</span>, «Não estou tentando escapar da morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:11</a> (cf. Jos., Vi. 141).—New Docs 3, 78. DELG s.v. <span class=\"greek\">αἰτέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακαθέζομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακαθέζομαι</span>, depoente médio; particípio do 1.º aoristo passivo <span class=\"greek\">παρακαθεσθείς</span> (Aristoph., Pla., X. e outros), sentar-se ao lado de (Jos., Ant. 8, 241): <span class=\"greek\">παρακαθεζόμενοι</span>, «Enquanto se sentavam ao lado (dele)», MPol 8:2. O aoristo passivo com sentido reflexivo ativo (como Jos., Ant. 6, 235) significa ter-se sentado junto, ter tomado lugar ao lado: <span class=\"greek\">ἣ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρακαθεσθεῖσα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἤκουεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">αὐτοῦ</span>, «A qual, depois de tomar lugar aos pés do Senhor, continuava ouvindo o que ele dizia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a>. Com dativo da pessoa ao lado da qual alguém se senta (Chariton 3, 3, 17; TestSol; TestJob 9:8 <span class=\"greek\">τῇ</span> <span class=\"greek\">θύρᾳ</span>; Jos., Ant. 6, 235 <span class=\"greek\">αὐτῷ</span>; 16, 50), GPt 12:53.—DELG s.v. <span class=\"greek\">ἕζομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακάθημαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακάθημαι</span> (Aristoph., Thu. e outros; inscrições, papiros, LXX), sentar-se ao lado, <span class=\"greek\">τινί</span> (assim, na maior parte das vezes; o acusativo é raro), «Sentar-se ao lado de alguém», Hs 5, 1, 1; 6, 1, 2; AcPl Ha 2, 10; 3, 2.—DELG s.v. <span class=\"greek\">ἧμαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακαθίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακαθίζω</span> (Pla. e outros, sobretudo na voz média, como Jos., Ant. 19, 264), em nossa literatura somente na voz ativa, sentar-se junto a, <span class=\"greek\">τινί</span>, alguém (Diod S 23, 9, 5; Plut., Mar. 415 [17, 3], Cleom. 823 [37, 16], Mor. 58d; Job 2:13; TestSol 17:2 P [<span class=\"greek\">π</span>. <span class=\"greek\">ἐμαυτόν</span>]; TestJob), Hv 5:2. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a>, variante textual.—DELG s.v. <span class=\"greek\">ἕζομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακαθίστημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακαθίστημι</span> (Isocr. e outros; inscrições, papiros; 2 Macc 12:3; Jos., Ant. 14, 438), colocar ou posicionar ao lado, postar: <span class=\"greek\">φύλακας</span>, «Guardas», Dg 2:7 (cf. Diod S 4, 63, 3 <span class=\"greek\">φύλακας</span>; Demosth. 4, 25; Plut., Fab. 7, 4 <span class=\"greek\">φυλακήν</span>).—DELG s.v. <span class=\"greek\">ἵστημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακαλέω</span>, imperfeito <span class=\"greek\">παρεκάλουν</span>; futuro <span class=\"greek\">παρακαλέσω</span> na LXX; 1.º aoristo <span class=\"greek\">παρεκάλεσα</span>. Passiva: 1.º futuro <span class=\"greek\">παρακληθήσομαι</span>; 1.º aoristo <span class=\"greek\">παρεκλήθην</span>; perfeito <span class=\"greek\">παρακέκλημαι</span> (Aeschyl., Hdt. e posteriores).<br>\n① Pedir a alguém que venha e esteja presente onde se encontra quem fala, chamar para junto de si.<br>\nⓐ <span class=\"greek\">τινά</span>, seguido de infinitivo para indicar a finalidade do chamado; talvez seja esse o caso de <span class=\"greek\">παρεκάλεσα</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἰδεῖν</span>, «Convoquei-vos para ver-vos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:20</a> (mas ver 3 abaixo).<br>\nⓑ Convidar, <span class=\"greek\">τινά</span>, alguém, seguido de infinitivo (que também pode ser suprido pelo contexto): <span class=\"greek\">παρεκάλει</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰσελθεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:41</a>. <span class=\"greek\">παρεκάλει</span> <span class=\"greek\">αὐτόν</span> (isto é, <span class=\"greek\">εἰσελθεῖν</span>), 15:28 (mas ver 5 abaixo). <span class=\"greek\">παρεκάλεσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Φίλιππον</span> <span class=\"greek\">καθίσαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:31</a> (cf. Jos., Ant. 12, 172). O conteúdo do convite segue em discurso direto, 9:38; introduzido por <span class=\"greek\">λέγουσα</span>, 16:15. Cf. <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">Μακεδών</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">παρακαλῶν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λέγων</span> … <span class=\"greek\">βοήθησον</span> <span class=\"greek\">ἡμῖν</span>, v. 9. Na passiva, seguido de infinitivo: <span class=\"greek\">παρακληθέντες</span> <span class=\"greek\">δειπνῆσαι</span>, «Quando sois convidados a jantar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a> D.—Algumas passagens da acepção 5 talvez pertençam a esta.<br>\nⓒ Convocar em auxílio, invocar por socorro (Hdt. e outros), especialmente a respeito de Deus, a quem se invoca em tempos de necessidade (Thu. 1, 118, 3; Pla., Leg. 2, 666b; 11 p. 917b; X., Hell. 2, 4, 17; Epict. 3, 21, 12; Jos., Ant. 6, 25; SIG 1170, 30f, relato de cura: <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">παρεκάλεσα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>. POxy 1070, 8f [III d.C.] <span class=\"greek\">τὸν</span> <span class=\"greek\">μέγαν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">Σάραπιν</span> <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ὑμῶν</span>; cf. restauração numa carta em papiro de Zoilo, servo de Serápis, em Dssm., LO 121, 11 [LAE 153, 4; carta, linha 8: <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">δ̣ὲ̣</span> <span class=\"greek\">π</span>[<span class=\"greek\">α</span>]<span class=\"greek\">ρ̣</span>[<span class=\"greek\">ακαλέσαντος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">Σάραπιν</span>]), <span class=\"greek\">τινά</span>: <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">μου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:53</a>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">παρεκάλεσα</span>, <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:8</a>. <span class=\"greek\">θεὸς</span> … <span class=\"greek\">παρακαλούμενος</span> <span class=\"greek\">ἀκούει</span>, «Deus atende quando é invocado», AcPt Ox 849, 27.<br>\n② Insistir vigorosamente, apelar, exortar, incentivar, encorajar (X. e outros; LXX), com acusativo de pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a> (mas ver 5 abaixo); 5:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a>; ITr 12:2; IRo 7:2. O acusativo encontra-se no contexto imediato, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:1</a> (mas ver 5 abaixo). Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:31</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">πολλῷ</span>, «Exortar alguém com muitas palavras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:2</a>; também <span class=\"greek\">τινὰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">πολλοῦ</span>, 15:32. <span class=\"greek\">τινὰ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ὀλίγων</span> <span class=\"greek\">γραμμάτων</span>, IPol 7:3. Com acusativo de pessoa e discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:1</a>; discurso direto introduzido por <span class=\"greek\">λέγων</span> (B-D-F §420), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a>. Com acusativo de pessoa e infinitivo (SIG 695, 43 [129 a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:23</a>; 27:33f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:1</a> (EKäsemann, Gottesdienst im Alltag, ’60 [Beih. ZNW], 165–71); 15:30; 16:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:8</a>; 6:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:11</a> (cf. Phlegon: 257 Fgm. 36 II, 4 Jac. p. 1172, 19; ELohse, ZNW 45, ’54, 68–89); Jd 3 (o acusativo se encontra no contexto imediato, como em Philo, Poster Cai. 138); ITr 6:1; IPhld 8:2; IPol 1:2a; Pol 9:1 e outros. Com infinitivo (acusativo no contexto) e continuação por <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅτι</span> (ver B-D-F §397, 6; Rob. 1047), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:22</a>. Com acusativo de pessoa e <span class=\"greek\">ἵνα</span> (PRyl 229, 17 [38 d.C.]; EpArist 318; Jos., Ant. 14, 168.—B-D-F §392, 1c; Rob. 1046), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:10</a>; 16:15f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a> (<span class=\"greek\">π</span>. com <span class=\"greek\">ἐρωτάω</span>, como BGU 1141, 10; POxy 294, 29); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:12</a>; Hm 12, 3, 2; AcPl Ha 7, 32. A oração com <span class=\"greek\">ἵνα</span> exprime não o conteúdo do apelo, como nas passagens citadas acima, mas sua finalidade: <span class=\"greek\">πάντας</span> <span class=\"greek\">παρακαλεῖν</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">σῴζωνται</span>, «Exortar todos para que sejam salvos», IPol 1:2b.—Sem acusativo de pessoa: seguido de discurso direto, <span class=\"greek\">ὡς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παρακαλοῦντος</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμῶν</span>· <span class=\"greek\">δεόμεθα</span>, «Visto que Deus, por assim dizer, faz seu apelo por nosso intermédio: ‘Suplicamos’», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:20</a>. Paulo atua como agente de Deus (como um «legado de César», Dssm. LO 320 [LAE 374]) e exerce a função de mediador (como Alexandre, o Grande, Plut., Mor. 329c <span class=\"greek\">διαλλακτής</span>; cf. também o papel mediador de um juiz, IPriene 53, especialmente 10f; ver ainda CBreytenbach, Versöhnung ’89, 64–66). Seguido de infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1</a>. Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a> (a acepção 4 também é possível); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:12</a> (com <span class=\"greek\">ἐπιμαρτυρεῖν</span>); B 19:10.—Com acusativo de coisa, inculcar algo a alguém, insistir, exortar: <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἕτερα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:18</a>. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">δίδασκε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρακάλει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:2</a>. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">λάλει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρακάλει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔλεγχε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:15</a>. No caso de várias passagens tratadas nesta seção, é possível classificá-las igualmente sob:<br>\n③ Fazer pedido insistente por alguma coisa, solicitar, implorar, suplicar (grego helenístico: Polyb., Diod S, Epict., Plut., inscrições, papiros, LXX, EpArist, Philo; Jos., Ant. 6, 143; 11, 338), com acusativo de pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:5</a>; 18:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:18</a>. <span class=\"greek\">πολλά</span>, «Suplicar insistentemente» (4 Macc 10:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:23</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «Suplicar a alguém a respeito de outra pessoa ou por ela», Phlm 10 (sobre a construção com <span class=\"greek\">περί</span>, cf. POxy 1070, 8). Acusativo seguido de discurso direto (ver BGU 846, 10 <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">σαι</span> [= <span class=\"greek\">σε</span>], <span class=\"greek\">μήτηρ</span>· <span class=\"greek\">διαλλάγηθί</span> <span class=\"greek\">μοι</span>; PGiss 12, 4; ParJer 1:4 e outros), introduzido por <span class=\"greek\">λέγων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:31</a>; 18:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:4</a> (variante textual <span class=\"greek\">ἠρώτων</span>). Com acusativo de pessoa e infinitivo (PTebt 12, 21 [II a.C.]; 1 Macc 9:35; Jos., Ant. 6, 25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:31</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:14</a>. Com acusativo de pessoa (facilmente subentendido pelo contexto, quando não expresso) e <span class=\"greek\">ὅπως</span> (Plut., Demetr. 907 [38, 11]; SIG 563, 4; 577, 44f [200/199 a.C.]; UPZ 109, 9 [98 a.C.]; PFlor 303, 3; 4 Macc 4:11; Jos., Ant. 13, 76), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:34</a> (variante textual <span class=\"greek\">ἵνα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:2</a>; IEph 3:2. Com acusativo de pessoa e <span class=\"greek\">ἵνα</span> (Epict. 2, 7, 11; PRyl 229, 17; EpArist 318.—B-D-F §392, 1c; Rob. 1046), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:18</a>; 6:56; 7:32; 8:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:31f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:5</a>. <span class=\"greek\">πολλά</span> <span class=\"greek\">τινα</span>, <span class=\"greek\">ἵνα</span>, «Suplicar insistentemente a alguém para que» (cf. TestNapht 9:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:12</a>. Com acusativo de pessoa e <span class=\"greek\">μή</span> seguido de subjuntivo, IRo 4:1. Com acusativo e infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:4</a>; na passiva, 13:42 (Just., D. 58, 1). Seguido de infinitivo substantivado com acusativo (B-D-F §400, 7; 409, 5; Rob. 1068; 1085), 21:12. <span class=\"greek\">παρεκάλεσα</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἰδεῖν</span>, «Pedi permissão para vos ver», 28:20 (mas ver 1a acima). Em uso absoluto, mas de modo que o acusativo seja facilmente recuperado do contexto, Phlm 9 (ParJer 9:4; Just., D. 46, 2; 74, 2 [sempre <span class=\"greek\">παρακαλῶ</span>, «por favor»]; cf. New Docs 8 p. 24, linha 7 [I a.C.]).<br>\n④ Infundir coragem ou ânimo em alguém, consolar, encorajar, animar (Plut., Otho 1074 [16, 2]; Gen 37:35; Ps 118:50; Job 4:3), com acusativo de pessoa (Sir 48:24; Jos., Bell. 1, 667; TestReub 4:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:4b</a>; 7:6a; 1 Cl 59:4; B 14:9 (Is 61:2); Hm 8:10. <span class=\"greek\">παρακαλεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «Consolar alguém com alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:6b</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τινα</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, «Consolar alguém a respeito de alguma coisa», 1:4a. <span class=\"greek\">π</span>. <span class=\"greek\">τινα</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, «Encorajar alguém em alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>. <span class=\"greek\">παρακαλεῖτε</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">τούτοις</span>, «Consolai-vos uns aos outros com estas palavras», 4:18.—Na passiva, ser consolado, receber consolo por palavras ou por uma mudança favorável na situação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:6</a>; 7:13; 13:11; deixar-se consolar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a> (Jer 38:15, variante textual). <span class=\"greek\">παρεκλήθημεν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμῖν</span>, «Fomos consolados a vosso respeito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:7</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παρακλήσει</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">παρεκλήθη</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:7</a>. <span class=\"greek\">διά</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρακλήσεως</span>, <span class=\"greek\">ἧς</span> (sobre atração, em lugar de <span class=\"greek\">ᾗ</span>, ver B-D-F §294, 2; Rob. 716) <span class=\"greek\">παρακαλούμεθα</span> <span class=\"greek\">αὐτοί</span>, «Pelo consolo com que nós mesmos somos consolados», 1:4c.—Com acusativo de coisa, <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:17</a>; na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a>.—Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a> (mas ver 2 acima). <span class=\"greek\">παρακαλεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διδασκαλίᾳ</span>, «Encorajar (os outros) mediante o ensino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:9</a>.—<span class=\"greek\">ἐλθόντες</span> <span class=\"greek\">παραεκάλεσαν</span> <span class=\"greek\">αὐτούς</span>, «(As autoridades) vieram e os tranquilizaram», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:39</a> (ver 5 abaixo).<br>\n⑤ Em várias passagens, <span class=\"greek\">παρ</span>. parece significar simplesmente tratar alguém de maneira convidativa ou cordial, algo como «estar aberto ao outro, manter a porta aberta»: convidar, conciliar, ser amigável ou falar amistosamente (cf. 2 Macc 13:23; Ar. 15, 5 [<span class=\"greek\">χριστιανοὶ</span>] <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀδικοῦντας</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">παρακαλοῦσιν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:28</a> (mas ver 1b: o pai procura repetidas vezes [imperfeito] fazer o filho participar da festa); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:39</a> (as autoridades agem conciliatoriamente, mas «pedir desculpas a» talvez seja interpretação excessiva; ver 4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:13</a> (de maneira semelhante a «manter a porta aberta»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:1</a>. Essas três últimas passagens também podem pertencer a 1b.—CBjerkelund, Parakalō ’67.—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακαλύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακαλύπτω</span>, particípio perfeito passivo <span class=\"greek\">παρακεκαλυμμένος</span> (Pla., Plut., LXX, Philo, Just.; Tat. 40, 1; Ath. 33, 2), ocultar, esconder, figuradamente (como Ezk 22:26; Philo, Decal. 91 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀλήθειαν</span>; Just., D. 107, 1; advérbio <span class=\"greek\">παρακεκαλυμμένως</span>: Just., D. 52, 1; 76, 2 e 6): <span class=\"greek\">ἦν</span> <span class=\"greek\">παρακεκαλυμμένον</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span>, «Estava oculto deles», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:45</a> (B-D-F §155, 3).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακαταθήκη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακαταθήκη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρακατατίθημι</span>; Hdt. e outros. Esta é a forma propriamente ática [ver <span class=\"greek\">παραθήκη</span>], mas também ocorre em Aristot., EN 5, 8, 5, 1135b, 4; Polyb. 5, 74, 5; Diod S 4, 58, 6; 15, 76, 1; Plut., Anton. 924 [21, 4]; Aelian, VH 4, 1; Vett. Val. p. 60, 21; ApcEsdr 6:3 p. 31, 7 Tdf. e outros [no sentido de «alma»]; Philo, Spec. Leg. 4, 30–38; Jos., Bell. 3, 372, Ant. 4, 285; inscrições, papiros, LXX), algo entregue para ser guardado, depósito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:14</a>, em ambos os casos variante textual (em lugar de <span class=\"greek\">παραθήκην</span>. Empregado com <span class=\"greek\">φυλάσσω</span>, como Socrat., Ep. 28, 6. Ver Mishnah: Baba Metzia 3; cf. Ps.-Phocyl. 13 <span class=\"greek\">παρθεσίην</span> <span class=\"greek\">τήρειν</span>, <span class=\"greek\">πίστιν</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">φυλάσσειν</span>, «Zela por um depósito e, em tudo, observa a fidelidade»; outras referências em PvanderHorst, The Sentences of Phocylides ’78, 120–21); Hm 3:2.—Ver DELG s.v. <span class=\"greek\">τίθημι</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράκειμαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράκειμαι</span> (X., Pla.; papiros, LXX, JosAs, EpArist, Philo; Just., D. 99, 2; Ath. 6, 1), estar presente e disponível para certa finalidade ou ação, estar à mão, pronto (assim Hom. e outros); em nossa literatura, somente com dativo de pessoa (<span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> p. 6, 10 V. [3, 5]; Lucian, De Merc. Cond. 26; PSI 542, 12 [III a.C.] <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">οὔπω</span> <span class=\"greek\">παράκειται</span> <span class=\"greek\">κέρμα</span> = «Ainda não tenho nenhum dinheiro à mão»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:18</a>, 21. Acerca de inclinações, GMary 463, 19 (ver <span class=\"greek\">ὀργίλος</span>).—JDerrett, Law in the NT, ’70 (bibliografia p. 30, n. 1).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακέκλημαι, παρακληθῶ</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακέκλημαι</span>, <span class=\"greek\">παρακληθῶ</span>: ver <span class=\"greek\">παρακαλέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακελεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακελεύω</span>, 1.º aoristo <span class=\"greek\">παρεκέλευσα</span> (como depoente médio em Hdt. e outros; papiros; Pr 9:16; EpArist, Philo; Jos., Ant. 12, 300; Just., A I, 4, 7; 16, 5.—A voz ativa em Hippocr. e outros; Plut., Mor. 195a; Appian, Bell. Civ. 5, 89 §372; 4 Macc 5:2), insistir vigorosamente, encorajar, exortar, <span class=\"greek\">τινά</span>, alguém (Polyb. 16, 20, 8), IMg 14.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0269-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράκλησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράκλησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρακαλέω</span>; Thu. e posteriores).<br>\n① Ato de infundir coragem em outra pessoa quanto a uma crença ou linha de ação, encorajamento, exortação (Thu. 8, 92, 11; Ps.-Pla., Def. 415e; Polyb. 1, 67, 10; 1, 72, 4; 22, 7, 2; Diod S 15, 56, 2; 2 Macc 7:24; Philo, Vi. Cont. 12; Jos., Vi. 87), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:5</a>. Com <span class=\"greek\">οἰκοδομή</span>: <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">παράκλησιν</span>, «Pronunciar palavras de exortação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:3</a>. <span class=\"greek\">παράκλησις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span>, «Exortação cristã», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:1</a> (a acepção 3 também é provável). Igualmente, a interpretação oscila entre 1 e 3 para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a> (ver <span class=\"greek\">παρακαλέω</span> 2 e 4).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:17</a> poderia ser colocado sob 1, mas provavelmente se classifica melhor sob 2. <span class=\"greek\">λόγος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>., «Palavra de exortação» (cf. 2 Macc 15:11 <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">παράκλησις</span>; 7:24; Dio Chrys. 1, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:22</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:15</a>. <span class=\"greek\">ἰσχυρὰν</span> <span class=\"greek\">παράκλησιν</span> <span class=\"greek\">ἔχειν</span>, «Ser grandemente encorajado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:18</a>.<br>\n② Pedido insistente, apelo, solicitação (Strabo 13, 1, 1; Appian, Liby. 51 §221; PTebt 392, 26; 36 [II d.C.]; PLond III, 1164d, 10 p. 159 [212 d.C.]; em papiros do VI d.C. frequentemente com <span class=\"greek\">δέησις</span>; 1 Macc 10:24; Jos., Ant. 3, 22): <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">δεόμενοι</span>, «Solicitando insistentemente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:4</a> (<span class=\"greek\">μετὰ</span> <span class=\"greek\">παρακλήσεως</span>, como Astrampsychus p. 28 Dec. 53, 5). <span class=\"greek\">παράκλησιν</span> <span class=\"greek\">ἐδέξατο</span>, «Ele aceitou (meu) apelo», v. 17 (Jos., Vi. 193; ver 1 acima; mas também Betz p. 70f).<br>\n③ Elevação do ânimo de outra pessoa, consolo, consolação (Epict. 3, 23, 28; Dio Chrys. 80 [30], 6; Phalaris, Ep. 103, 1; Jer 16:7; Hos 13:14; Na 3:7; Job 21:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:4</a>–7; 7:4, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:1</a> (ver 1 acima); Phlm 7. <span class=\"greek\">παράκλησις</span> <span class=\"greek\">αἰωνία</span>, «Consolo eterno (= inesgotável)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:16</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">γραφῶν</span>, «A consolação proporcionada pelas Escrituras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:4</a> (cf. 1 Macc 12:9 <span class=\"greek\">παράκλησιν</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">βιβλία</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἅγια</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>., «O Deus da consolação», v. 5; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:3</a>. Acerca de circunstâncias, acontecimentos etc. consoladores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:7</a>.—Em sentido escatológico (Ps.-Clem., Hom. 3, 26 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέλλοντι</span> <span class=\"greek\">αἰῶνι</span>): <span class=\"greek\">προσδεχόμενος</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span>, «Aguardando a consolação de Israel» (isto é, a salvação messiânica; ver Is 40:1; 61:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:25</a> (ver Dalman, Worte 89f; Billerb. II 124–26.—Em épocas posteriores, os judeus por vezes chamavam o próprio Messias de <span class=\"hebrew\" dir=\"rtl\">מְנַחֵם</span> = «consolador»; ver Billerb. I 66; Bousset, Rel.3 227).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:36</a>: o nome Barnabé é traduzido <span class=\"greek\">υἱὸς</span> <span class=\"greek\">παρακλήσεως</span> (ver <span class=\"greek\">βαρναβᾶς</span> e também Dalman, Gramm.2, 178, 4).—DELG s.v. <span class=\"greek\">καλέω</span>. M-M. TW. Sv.</p></section></article>"};
